    // Names as the services call themselves, to the Simple Icons name.
    private val ALIASES = mapOf("chromecast" to "googlecast", "itvhub" to "itvx", "hue" to "philipshue", "ytmusic" to "youtubemusic")

private fun serviceSlug(name: String): String {
    val k = name.trim().lowercase().replace("+", "plus").replace("&", "and").replace(".", "dot").replace(Regex("[^a-z0-9]"), "")
    return ALIASES[k] ?: k
}

/** Whether the watch has a logo for the service [name] ("Spotify", "YouTube Music"). */
fun hasServiceLogo(name: String) = serviceSlug(name) in SERVICE_PATHS

/** The logo of the service [name] in one colour, or nothing when the watch has none. */
@Composable
fun ServiceLogo(name: String, tint: Color, size: Dp, modifier: Modifier = Modifier) {
    val d = SERVICE_PATHS[serviceSlug(name)] ?: return
    val path = remember(d) { PathParser().parsePathString(d).toPath() }
    Canvas(modifier.size(size)) {
        val s = this.size.minDimension / 24f
        scale(s, s, pivot = Offset.Zero) { drawPath(path, color = tint) }
    }
}
